/*
 * tm-helper.js — Teachable Machine helper for student apps
 * ---------------------------------------------------------
 * DO NOT EDIT THIS FILE. Build your app in index.html.
 *
 * Wraps the official Teachable Machine image library (lib/teachablemachine-image.min.js)
 * so an app can load a model that was downloaded to the laptop, with no installs and
 * no local web server. Works when index.html is opened by double-clicking it.
 *
 * Public API (global `TM`):
 *   await TM.loadModel()                 -> string[] of class labels
 *   await TM.startWebcam(elementOrId, { size: 300 })
 *   TM.onPrediction(fn, { everyMs: 100 }) -> fn({ label, confidence, all }) repeatedly
 *   await TM.classify(imageOrCanvasOrVideo) -> { label, confidence, all }
 *   TM.stopWebcam()
 *   TM.labels                            -> string[] (after loadModel)
 *
 * `confidence` is 0..1. `all` is [{ label, confidence }, ...] in the model's class order.
 *
 * How the model is found, in order:
 *   1. model/model-bundle.js (saved by this helper; works from double-click / file://)
 *   2. model/model.json + metadata.json + weights.bin (only when served over http/https)
 *   3. Otherwise a drop zone asks for the Teachable Machine .zip (or its 3 files).
 */
(function () {
  'use strict';

  if (typeof tmImage === 'undefined' || typeof tf === 'undefined') {
    alert('tm-helper.js: load lib/tf.min.js and lib/teachablemachine-image.min.js BEFORE tm-helper.js');
    return;
  }

  let model = null;
  let webcam = null;
  let loopRunning = false;
  const listeners = [];

  // ---------- result formatting ----------
  function format(raw) {
    const all = raw.map(p => ({ label: p.className, confidence: p.probability }));
    let best = all[0];
    for (const p of all) if (p.confidence > best.confidence) best = p;
    return { label: best.label, confidence: best.confidence, all };
  }

  // ---------- model loading ----------
  function filesFromBundle(bundle) {
    const files = [];
    for (const name of Object.keys(bundle.files)) {
      const entry = bundle.files[name];
      let data;
      if (entry.base64) {
        const bin = atob(entry.base64);
        data = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) data[i] = bin.charCodeAt(i);
      } else {
        data = entry.text;
      }
      files.push(new File([data], name));
    }
    return files;
  }

  // Sort a list of File objects into what tmImage.loadFromFiles needs.
  function pickModelFiles(files) {
    const byName = {};
    for (const f of files) byName[f.name.split('/').pop().toLowerCase()] = f;
    if (byName['keras_model.h5'] || byName['labels.txt'] && !byName['model.json']) {
      throw new Error('That is the Keras download. In Teachable Machine click "Export Model", choose the "Tensorflow.js" tab, then "Download my model".');
    }
    if (byName['model.tflite'] || Object.keys(byName).some(n => n.endsWith('.tflite'))) {
      throw new Error('That is the TensorFlow Lite download. In Teachable Machine click "Export Model", choose the "Tensorflow.js" tab, then "Download my model".');
    }
    const modelJson = byName['model.json'];
    const metadata = byName['metadata.json'];
    const weights = files.find(f => f.name.toLowerCase().endsWith('.bin'));
    const missing = [];
    if (!modelJson) missing.push('model.json');
    if (!metadata) missing.push('metadata.json');
    if (!weights) missing.push('weights.bin');
    if (missing.length) throw new Error('Missing ' + missing.join(', ') + '. Drop the whole .zip from Teachable Machine, or all 3 files together.');
    return { modelJson, weights, metadata };
  }

  async function loadFromFileList(files) {
    const f = pickModelFiles(files);
    model = await tmImage.loadFromFiles(f.modelJson, f.weights, f.metadata);
    return f;
  }

  async function tryHttpFolder() {
    if (location.protocol !== 'http:' && location.protocol !== 'https:') return false;
    try {
      const res = await fetch('model/model.json', { method: 'HEAD' });
      if (!res.ok) return false;
      model = await tmImage.load('model/model.json', 'model/metadata.json');
      return true;
    } catch (e) {
      return false;
    }
  }

  async function loadModel() {
    if (model) return model.getClassLabels();

    // 1. Saved bundle (works from file://)
    if (window.TM_MODEL_BUNDLE) {
      await loadFromFileList(filesFromBundle(window.TM_MODEL_BUNDLE));
    // 2. Plain files in model/ when served over http
    } else if (!(await tryHttpFolder())) {
      // 3. Ask the student for the files
      await askForModel();
    }
    // Warm up so the first real prediction is fast.
    const warm = document.createElement('canvas');
    warm.width = warm.height = 224;
    await model.predict(warm);
    TM.labels = model.getClassLabels();
    return TM.labels;
  }

  // ---------- zip reading (no library needed) ----------
  async function inflateRaw(bytes) {
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
    return new Uint8Array(await new Response(stream).arrayBuffer());
  }

  async function unzip(file) {
    const buf = new Uint8Array(await file.arrayBuffer());
    const dv = new DataView(buf.buffer);
    let eocd = -1;
    for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) {
      if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
    }
    if (eocd < 0) throw new Error(file.name + ' is not a valid .zip file.');
    const count = dv.getUint16(eocd + 10, true);
    let p = dv.getUint32(eocd + 16, true);
    const out = [];
    const dec = new TextDecoder();
    for (let n = 0; n < count; n++) {
      if (dv.getUint32(p, true) !== 0x02014b50) break;
      const method = dv.getUint16(p + 10, true);
      const compSize = dv.getUint32(p + 20, true);
      const nameLen = dv.getUint16(p + 28, true);
      const extraLen = dv.getUint16(p + 30, true);
      const commentLen = dv.getUint16(p + 32, true);
      const localOff = dv.getUint32(p + 42, true);
      const name = dec.decode(buf.subarray(p + 46, p + 46 + nameLen));
      p += 46 + nameLen + extraLen + commentLen;
      if (name.endsWith('/') || name.startsWith('__MACOSX') || name.split('/').pop().startsWith('.')) continue;
      const lNameLen = dv.getUint16(localOff + 26, true);
      const lExtraLen = dv.getUint16(localOff + 28, true);
      const start = localOff + 30 + lNameLen + lExtraLen;
      const raw = buf.subarray(start, start + compSize);
      let data;
      if (method === 0) data = raw.slice();
      else if (method === 8) data = await inflateRaw(raw);
      else throw new Error('Unsupported zip compression in ' + name);
      out.push(new File([data], name.split('/').pop()));
    }
    return out;
  }

  // Expand dropped items: .zip files, plain files, or a dropped folder.
  async function collectFiles(fileList, items) {
    let files = [];
    if (items && items.length && items[0].webkitGetAsEntry) {
      const entries = Array.from(items).map(i => i.webkitGetAsEntry()).filter(Boolean);
      if (entries.some(e => e.isDirectory)) {
        const walk = entry => new Promise(resolve => {
          if (entry.isFile) return entry.file(f => resolve([f]), () => resolve([]));
          entry.createReader().readEntries(async ents => {
            const nested = await Promise.all(ents.map(walk));
            resolve(nested.flat());
          }, () => resolve([]));
        });
        files = (await Promise.all(entries.map(walk))).flat();
      }
    }
    if (!files.length) files = Array.from(fileList);
    const expanded = [];
    for (const f of files) {
      if (f.name.toLowerCase().endsWith('.zip')) expanded.push(...(await unzip(f)));
      else expanded.push(f);
    }
    return expanded;
  }

  // ---------- saving the bundle so the drop step happens only once ----------
  async function makeBundle(files) {
    const toB64 = async f => {
      const bytes = new Uint8Array(await f.arrayBuffer());
      let s = '';
      for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      return btoa(s);
    };
    const bundle = { createdBy: 'tm-helper.js', savedAt: new Date().toISOString(), files: {} };
    bundle.files[files.modelJson.name] = { text: await files.modelJson.text() };
    bundle.files[files.metadata.name] = { text: await files.metadata.text() };
    bundle.files[files.weights.name] = { base64: await toB64(files.weights) };
    const js = '// Teachable Machine model saved by tm-helper.js. Large file: do not open or edit.\n' +
      'window.TM_MODEL_BUNDLE = ' + JSON.stringify(bundle) + ';\n';
    return new Blob([js], { type: 'text/javascript' });
  }

  // ---------- drop-zone UI ----------
  const CSS = `
  .tmh-overlay{position:fixed;inset:0;background:rgba(15,23,42,.88);display:flex;align-items:center;justify-content:center;z-index:99999;font:16px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#0f172a}
  .tmh-card{background:#fff;border-radius:16px;padding:28px;max-width:520px;width:calc(100% - 40px);box-shadow:0 20px 50px rgba(0,0,0,.4)}
  .tmh-card h2{margin:0 0 8px;font-size:22px}
  .tmh-card p{margin:6px 0;color:#334155}
  .tmh-drop{margin-top:16px;border:3px dashed #94a3b8;border-radius:12px;padding:32px 16px;text-align:center;cursor:pointer;transition:.15s}
  .tmh-drop.over{border-color:#2563eb;background:#eff6ff}
  .tmh-drop strong{display:block;font-size:18px;margin-bottom:4px}
  .tmh-err{color:#b91c1c;margin-top:12px;font-weight:600}
  .tmh-btn{display:inline-block;margin-top:14px;padding:10px 16px;border-radius:10px;border:0;background:#2563eb;color:#fff;font:inherit;font-weight:600;cursor:pointer}
  .tmh-btn.secondary{background:#e2e8f0;color:#0f172a;margin-left:8px}
  .tmh-banner{position:fixed;left:16px;right:16px;bottom:16px;z-index:99998;background:#fff;color:#0f172a;border-radius:14px;padding:14px 18px;box-shadow:0 10px 30px rgba(0,0,0,.25);font:15px/1.4 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:640px;margin:0 auto}
  .tmh-banner .tmh-btn{margin-top:8px}
  `;

  function injectCss() {
    if (document.getElementById('tmh-css')) return;
    const s = document.createElement('style');
    s.id = 'tmh-css';
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  function askForModel() {
    injectCss();
    return new Promise(resolve => {
      const overlay = document.createElement('div');
      overlay.className = 'tmh-overlay';
      overlay.innerHTML = `
        <div class="tmh-card">
          <h2>Load your Teachable Machine model</h2>
          <p>In Teachable Machine: <b>Export Model</b> → <b>Tensorflow.js</b> tab → <b>Download my model</b>.</p>
          <div class="tmh-drop" tabindex="0">
            <strong>Drop the downloaded .zip here</strong>
            or click to choose it (you can also pick the 3 files: model.json, metadata.json, weights.bin)
          </div>
          <input type="file" multiple accept=".zip,.json,.bin" hidden>
          <div class="tmh-err" hidden></div>
        </div>`;
      document.body.appendChild(overlay);
      const drop = overlay.querySelector('.tmh-drop');
      const input = overlay.querySelector('input');
      const err = overlay.querySelector('.tmh-err');

      async function handle(fileList, items) {
        err.hidden = true;
        drop.querySelector('strong').textContent = 'Loading model…';
        try {
          const files = await collectFiles(fileList, items);
          const picked = await loadFromFileList(files);
          overlay.remove();
          offerSave(picked);
          resolve();
        } catch (e) {
          console.error(e);
          err.textContent = e.message || String(e);
          err.hidden = false;
          drop.querySelector('strong').textContent = 'Drop the downloaded .zip here';
        }
      }

      drop.addEventListener('click', () => input.click());
      drop.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') input.click(); });
      input.addEventListener('change', () => handle(input.files));
      ['dragenter', 'dragover'].forEach(t => overlay.addEventListener(t, e => { e.preventDefault(); drop.classList.add('over'); }));
      overlay.addEventListener('dragleave', e => { if (e.target === overlay) drop.classList.remove('over'); });
      overlay.addEventListener('drop', e => {
        e.preventDefault();
        drop.classList.remove('over');
        handle(e.dataTransfer.files, e.dataTransfer.items);
      });
    });
  }

  function offerSave(picked) {
    const banner = document.createElement('div');
    banner.className = 'tmh-banner';
    banner.innerHTML = `
      <b>Model loaded!</b> To skip this step every time you reload:
      click <b>Save model to project</b>, then move the downloaded
      <code>model-bundle.js</code> into this project's <code>model</code> folder.<br>
      <button class="tmh-btn">Save model to project</button>
      <button class="tmh-btn secondary">Not now</button>`;
    document.body.appendChild(banner);
    const [save, later] = banner.querySelectorAll('button');
    later.onclick = () => banner.remove();
    save.onclick = async () => {
      save.disabled = true;
      save.textContent = 'Preparing…';
      const blob = await makeBundle(picked);
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'model-bundle.js';
      document.body.appendChild(a);
      a.click();
      a.remove();
      banner.innerHTML = '<b>Downloaded model-bundle.js.</b> Move it from your Downloads folder into this project\'s <code>model</code> folder, then reload the page.<br><button class="tmh-btn secondary">OK</button>';
      banner.querySelector('button').onclick = () => banner.remove();
    };
  }

  // ---------- webcam + prediction loop ----------
  async function startWebcam(target, opts) {
    opts = opts || {};
    const size = opts.size || 300;
    if (!model) await loadModel();
    const el = typeof target === 'string' ? (document.getElementById(target) || document.querySelector(target)) : target;
    if (!el) throw new Error('TM.startWebcam: could not find element ' + target);
    // flip=true mirrors the picture like Teachable Machine's training webcam.
    webcam = new tmImage.Webcam(size, size, true);
    try {
      await webcam.setup();
    } catch (e) {
      throw new Error('Could not start the webcam. Allow camera access in the browser and close other apps using the camera. (' + (e.message || e.name) + ')');
    }
    await webcam.play();
    el.appendChild(webcam.canvas);
    webcam.canvas.style.maxWidth = '100%';
    startLoop();
    return webcam.canvas;
  }

  function stopWebcam() {
    loopRunning = false;
    if (webcam) {
      webcam.stop();
      if (webcam.canvas && webcam.canvas.parentNode) webcam.canvas.parentNode.removeChild(webcam.canvas);
      webcam = null;
    }
  }

  function onPrediction(fn, opts) {
    listeners.push({ fn, everyMs: (opts && opts.everyMs) || 100, last: 0 });
    startLoop();
  }

  let loopId = 0;
  function startLoop() {
    if (loopRunning || !webcam || !listeners.length) return;
    loopRunning = true;
    const myLoop = ++loopId; // so a stopped-then-restarted webcam never runs two loops
    let busy = false;
    const tick = async now => {
      if (!loopRunning || !webcam || myLoop !== loopId) return;
      webcam.update();
      const due = listeners.filter(l => now - l.last >= l.everyMs);
      if (due.length && !busy) {
        busy = true;
        try {
          // The webcam canvas is already mirrored, so no extra flip here.
          const result = format(await model.predict(webcam.canvas));
          for (const l of due) {
            l.last = now;
            try { l.fn(result); } catch (e) { console.error('Error in your onPrediction code:', e); }
          }
        } finally {
          busy = false;
        }
      }
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }

  async function classify(source) {
    if (!model) await loadModel();
    if (source instanceof HTMLImageElement) {
      if (!source.complete || !source.naturalWidth) {
        await new Promise((res, rej) => {
          source.addEventListener('load', res, { once: true });
          source.addEventListener('error', () => rej(new Error('Could not load that image.')), { once: true });
        });
      }
      // The library reads img.width (the on-screen size), which squashes photos shown
      // with CSS sizing. Copy the image at its real size so the model sees a true center crop.
      const c = document.createElement('canvas');
      c.width = source.naturalWidth;
      c.height = source.naturalHeight;
      c.getContext('2d').drawImage(source, 0, 0);
      source = c;
    }
    return format(await model.predict(source));
  }

  window.TM = {
    loadModel,
    startWebcam,
    stopWebcam,
    onPrediction,
    classify,
    labels: [],
    get model() { return model; }
  };
})();
